using MediatR; using JTradeERP.Application.Common.Persistence; using JTradeERP.Application.Common.Exceptions; namespace JTradeERP.Application.Features.MasterData.Categories.ActivateCategory; public sealed class ActivateCategoryHandler(IApplicationDbContext db) : IRequestHandler<ActivateCategoryCommand, ActivateCategoryResponse> { public async Task<ActivateCategoryResponse> Handle(ActivateCategoryCommand r,CancellationToken ct){var e=db.Categories.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("Category not found.");e.Activate();await db.SaveChangesAsync(ct);return new(e.Id,e.Name,e.IsActive);} }
